-- Only promote untouched non-art drafts. Art records and editor changes are protected.
begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"377e808e-87b2-5a7b-a114-650880916ec3","inventory_key":"art-audit:z44","name":"Kunstpunt Groningen","city":"Groningen","province":"Groningen","street_address":"Trompsingel 27a","postal_code":"9724 DA","country":"NL","website_url":"https://www.kunstpuntgroningen.nl","latitude":null,"longitude":null,"summary":"Ontdek beeldende kunst in Groningen, binnen én buiten. Kunstpunt verbindt tentoonstellingen en kunstuitleen met verhalen over kunst in de openbare ruimte. Een toegankelijk vertrekpunt voor nieuwe ontmoetingen met makers en beelden.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","kunst in openbare ruimte"],"photos":[],"is_art_museum":true},{"id":"3eccb19d-2772-5ae1-be07-8d3fb319ac9a","inventory_key":"art-audit:z47","name":"MaMA","city":"Rotterdam","province":"Zuid-Holland","street_address":"Witte de Withstraat 29-31","postal_code":"3012 BL","country":"NL","website_url":"https://thisismama.nl/","latitude":null,"longitude":null,"summary":"Ontdek kunst en beeldcultuur vanuit een jonge generatie. MAMA geeft opkomende makers ruimte om tentoonstellingen en projecten te ontwikkelen. Nieuwe vormen en perspectieven laten zien hoe kunst midden in het dagelijks leven staat.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","beeldcultuur","jong talent"],"photos":[],"is_art_museum":true},{"id":"cf4febc1-45cc-53e6-93c6-37e464ac551f","inventory_key":"art-audit:z51","name":"Mediamatic","city":"Amsterdam","province":"Noord-Holland","street_address":"Biotoop Dijkspark, Dijksgracht 6","postal_code":"1019 BS","country":"NL","website_url":"https://www.mediamatic.net","latitude"