lication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","experiment","kunsthal"],"photos":[],"is_art_museum":true},{"id":"7e6ef733-4a4e-514a-909c-addda45d4cc3","inventory_key":"art-audit:z59","name":"NP3 | eMMa Rem Koolhaas Videobusstop","city":"Groningen","province":"Groningen","street_address":"Emmaplein","postal_code":"9711AP","country":"NL","website_url":"https://www.np3.nu/","latitude":null,"longitude":null,"summary":"Ontdek videokunst op een onverwachte plek. NP3 gebruikt de door Rem Koolhaas ontworpen videobusstop eMMa als podium. Bewegend beeld wordt hier onderdeel van de dagelijkse stad; bekijk vooraf het actuele programma.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["videokunst","mediakunst","openlucht"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Groningen_Koolhaas_01.JPG/1280px-Groningen_Koolhaas_01.JPG","caption":"NP3 | eMMa Rem Koolhaas Videobusstop — Groningen Koolhaas 01","credit":"Gerardus","source_url":"https://commons.wikimedia.org/wiki/File:Groningen_Koolhaas_01.JPG","license":"Public domain"}],"is_art_museum":true},{"id":"1b5450c8-f2d7-56e7-a330-8a109b5c0278","inventory_key":"art-audit:z60","name":"NP3 | MOBi","city":"Groningen","province":"Groningen","street_address":"Suikerlaan 41","postal_code":"9743 DA","country":"NL","website_url":"https://www.np3.nu/","latitude":null,"longitude":null,"summary":"Ontdek experimenten bij de MOBi-locatie van NP3. Kunstenaars onderzoeken nieuwe vormen, materialen en ideeën in wisselende projecten. Deze plek biedt ruimte aan werk dat buiten vertrouwde tentoonstellingsvormen treedt.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","experiment","kunsthal"],"photos":[],"is_art_museum":true},{"id":"b9f3af95-3427-535f-b2de-f293758b2a34","inventory_key":"art-audit:z61","name":"NP3 | RE:Search:Gallery","city":"Groningen","province":"G