uwe makers bij SIGN. De Groningse kunstruimte geeft jonge kunstenaars gelegenheid om onderzoek en experiment te presenteren. Wisselende projecten laten zien hoe eigenzinnige ideeën hun eerste vorm krijgen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","jong talent","experiment"],"photos":[],"is_art_museum":true},{"id":"abe68e6d-4b1c-5277-9a09-7a0abec22d74","inventory_key":"art-audit:z83","name":"EST art foundation","city":"Leiden","province":"Zuid-Holland","street_address":"Papegaaisbolwerk 20","postal_code":"2312 LW","country":"NL","website_url":"https://est-art-foundation.org","latitude":null,"longitude":null,"summary":"Ontdek uiteenlopende beeldende disciplines bij EST art foundation. Tentoonstellingen brengen makers en werken in nieuwe combinaties samen. De onafhankelijke plek in Leiden biedt ruimte aan experiment en een persoonlijke blik.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal"],"photos":[],"is_art_museum":true},{"id":"2399fffa-6f31-5919-b340-6153d1689312","inventory_key":"art-audit:z86","name":"Van Abbehuis","city":"Eindhoven","province":"Noord-Brabant","street_address":"Stadhuisplein 3","postal_code":"5611 EM","country":"NL","website_url":"https://vanabbehuis.com/nl/","latitude":null,"longitude":null,"summary":"Ontdek hedendaagse kunst bij Van Abbehuis. Tijdens de verbouwing vinden presentaties plaats aan het Stadhuisplein. Wisselende tentoonstellingen geven verschillende makers ruimte; bekijk voor bezoek de actuele locatie op de website.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/GM_407_Designhuis_Stadhuisplein_3%2C_Eindhoven.jpg/1280px-GM_407_Designhuis_Stadhuisplein_3%2C_Eindhoven.jpg","caption":"Van Abbehuis — GM 407 Designhuis Stadhuisplein 3, Eindhoven","credit":"Rosemoon","source_url":"https://commons.wikimedia.org/wiki/File:GM_407_Designhuis_Stadhuisplein_3,_Eindhoven.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
